// #region 15. SHADER PASSES
import { THREE, React } from "../core/deps.tsx"
import { TONE_MAPPINGS } from "../core/constants.tsx"

export const useBrowserLayoutEffect =
    typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/**
 * Framer/Figma-style tile pixelation. Unlike Three.js RenderPixelatedPass,
 * this operates on the finished image and exposes shaped cells, gaps,
 * posterization, average color, dissolve and knockout behavior.
 */
export const FramerTilePixelateShader = {
    uniforms: {
        tDiffuse: { value: null },
        resolution: { value: new THREE.Vector2(1, 1) },
        shape: { value: 0 },
        cellPx: { value: new THREE.Vector2(23, 23) },
        gap: { value: 0 },
        colorTrim: { value: 0 },
        averageColor: { value: 0.42 },
        dissolve: { value: 0 },
        falloff: { value: 0 },
        dissolveMode: { value: 0 },
        knockout: { value: 1 },
    },
    vertexShader: `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform vec2 resolution;
        uniform int shape;
        uniform vec2 cellPx;
        uniform float gap;
        uniform float colorTrim;
        uniform float averageColor;
        uniform float dissolve;
        uniform float falloff;
        uniform int dissolveMode;
        uniform float knockout;
        varying vec2 vUv;

        vec4 sampleSrc(vec2 uv) {
            if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
                return vec4(0.0);
            }
            return texture2D(tDiffuse, uv);
        }

        float hash12(vec2 p) {
            // Keep this compatible with the GLSL ES 1.00 compiler used by
            // WebGL1.  The more compact vec3 hash is valid in newer GLSL
            // versions, but some browsers reject it when this pass is
            // compiled through ShaderMaterial.
            return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
        }

        float hexDist(vec2 p) {
            p = abs(p);
            return max(dot(p, vec2(0.5, 0.866025)), p.x);
        }

        vec4 hexCoords(vec2 g) {
            vec2 r = vec2(1.0, 1.7320508);
            vec2 h = r * 0.5;
            vec2 a = mod(g, r) - h;
            vec2 b = mod(g - h, r) - h;
            vec2 gv = a;
            if (dot(b, b) < dot(a, a)) gv = b;
            return vec4(gv, g - gv);
        }

        void main() {
            vec2 px = vUv * resolution;
            vec2 g = px / cellPx;
            float gapHalf = gap * 0.5;
            vec2 centerCell;
            float mask;
            float dropped = 0.0;

            if (shape == 0 || shape == 1) {
                vec2 id = floor(g);
                centerCell = id + 0.5;
                vec2 lc = g - centerCell;
                float th = 0.5 - gapHalf;
                if (shape == 0) {
                    // With no gap, every fragment belongs to a rectangle
                    // cell. The strict edge test would otherwise leave a
                    // one-pixel knockout line at each tile boundary.
                    if (gap < 0.0001) mask = 1.0;
                    else if (max(abs(lc.x), abs(lc.y)) < th) mask = 1.0;
                    else mask = 0.0;
                } else {
                    if (length(lc) < th) mask = 1.0;
                    else mask = 0.0;
                }
            } else if (shape == 2) {
                vec4 hc = hexCoords(g);
                centerCell = hc.zw;
                if (hexDist(hc.xy) < 0.5 * (1.0 - gap)) mask = 1.0;
                else mask = 0.0;
            } else {
                vec2 id = floor(g);
                vec2 lc = g - (id + 0.5);
                float diag = mod(id.x + id.y, 2.0);
                float s;
                if (diag < 0.5) s = lc.x + lc.y;
                else s = lc.x - lc.y;
                float tri = step(0.0, s);
                vec2 cen;
                if (diag < 0.5) {
                    if (tri > 0.5) cen = vec2(1.0 / 6.0);
                    else cen = vec2(-1.0 / 6.0);
                } else {
                    if (tri > 0.5) cen = vec2(1.0, -1.0) / 6.0;
                    else cen = vec2(-1.0, 1.0) / 6.0;
                }
                centerCell = id + 0.5 + cen;
                float dEdge = 0.5 - max(abs(lc.x), abs(lc.y));
                float dDiag = abs(s) / 1.4142136;
                if (min(dEdge, dDiag) > gapHalf) mask = 1.0;
                else mask = 0.0;
            }

            vec2 centerUv = centerCell * cellPx / resolution;
            vec4 centerCol = sampleSrc(centerUv);
            vec4 avg = vec4(0.0);
            for (int y = -1; y <= 1; y++) {
                for (int x = -1; x <= 1; x++) {
                    vec2 o = vec2(float(x), float(y)) * cellPx * 0.3 / resolution;
                    avg += sampleSrc(centerUv + o);
                }
            }
            avg /= 9.0;
            vec4 col = mix(centerCol, avg, averageColor);

            float steps = max(1.0, 256.0 / exp2(colorTrim));
            col.rgb = floor(col.rgb * steps) / steps;

            float bias = mix(1.0, smoothstep(0.0, 1.0, centerUv.y), falloff);
            float chance = dissolve * bias;
            float randomCell = hash12(centerCell);
            if (dissolveMode == 0) {
                if (randomCell < chance) dropped = 1.0;
            } else if (dissolve > 0.0) {
                col.a *= 1.0 - smoothstep(chance, chance + 0.2, randomCell);
            }

            if (mask > 0.5 && dropped < 0.5) {
                gl_FragColor = col;
            } else if (dropped > 0.5 && knockout > 0.5) {
                // Only a deliberately dissolved cell may become transparent.
                // Shape boundaries are not gaps anymore: preserving the
                // source pixel there prevents the geometric glitch pattern
                // seen when switching Ellipse/Triangle at small sizes.
                gl_FragColor = vec4(0.0);
            } else {
                gl_FragColor = sampleSrc(vUv);
            }
        }
    `,
}

const TILE_PIXELATE_SHAPES = {
    rectangle: 0,
    ellipse: 1,
    hexagon: 2,
    triangle: 3,
}

const _clamp01 = (value: number) => Math.max(0, Math.min(1, value))

export function createFramerTilePixelatePass(ShaderPass: any) {
    const pass = new ShaderPass(FramerTilePixelateShader)
    const uniforms = pass.uniforms || pass.material?.uniforms
    pass._pixelRatio = 1
    pass._tileConfig = null

    pass.setSize = (width: number, height: number) => {
        uniforms.resolution.value.set(Math.max(1, width), Math.max(1, height))
    }

    pass.setPixelRatio = (pixelRatio: number) => {
        pass._pixelRatio = Math.max(0.5, pixelRatio || 1)
        if (pass._tileConfig) pass.setTilePixelateConfig(pass._tileConfig)
    }

    pass.setTilePixelateConfig = (cfg: any) => {
        pass._tileConfig = cfg
        const size = Math.max(1, Number(cfg.pixelateSize) || 23)
        const stretch = Math.max(-90, Number(cfg.pixelateStretch) || 0)
        const widthFactor = Math.max(0.1, 1 + stretch / 100)
        const shape = TILE_PIXELATE_SHAPES[cfg.pixelateShape] ?? 0
        // Work on whole physical pixels. Fractional cell sizes (for example
        // 3 CSS px on a 1.5 DPR display) make the hex lattice phase drift and
        // produce unstable moire/pattern pixels while resizing.
        const cellWidthPx = Math.max(
            1,
            Math.round(size * widthFactor * pass._pixelRatio)
        )
        const cellHeightPx = Math.max(
            1,
            Math.round(size * pass._pixelRatio)
        )
        uniforms.shape.value = shape
        uniforms.cellPx.value.set(
            cellWidthPx,
            cellHeightPx
        )
        // Gap and color trim are intentionally disabled. Pixelate must not
        // introduce a color or dotted/knockout pattern of its own.
        uniforms.gap.value = 0
        uniforms.colorTrim.value = 0
        uniforms.averageColor.value = _clamp01(
            (Number(cfg.pixelateAverageColor) || 0) / 100
        )
        uniforms.dissolve.value = _clamp01(
            (Number(cfg.pixelateDissolve) || 0) / 100
        )
        uniforms.falloff.value = _clamp01(
            (Number(cfg.pixelateFalloff) || 0) / 100
        )
        uniforms.dissolveMode.value = cfg.pixelateDissolveMode === "fade" ? 1 : 0
        uniforms.knockout.value = cfg.pixelateKnockout === false ? 0 : 1
    }

    return pass
}

// Shared 3D Noise GLSL (Perlin-like)
export const NOISE_GLSL = `
    vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
    vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

    float snoise(vec3 v) {
        const vec2 C = vec2(1.0/6.0, 1.0/3.0);
        const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
        vec3 i  = floor(v + dot(v, C.yyy));
        vec3 x0 = v - i + dot(i, C.xxx);
        vec3 g = step(x0.yzx, x0.xyz);
        vec3 l = 1.0 - g;
        vec3 i1 = min(g.xyz, l.zxy);
        vec3 i2 = max(g.xyz, l.zxy);
        vec3 x1 = x0 - i1 + C.xxx;
        vec3 x2 = x0 - i2 + C.yyy;
        vec3 x3 = x0 - D.yyy;
        i = mod289(i);
        vec4 p = permute(permute(permute(
            i.z + vec4(0.0, i1.z, i2.z, 1.0))
            + i.y + vec4(0.0, i1.y, i2.y, 1.0))
            + i.x + vec4(0.0, i1.x, i2.x, 1.0));
        float n_ = 0.142857142857;
        vec3 ns = n_ * D.wyz - D.xzx;
        vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
        vec4 x_ = floor(j * ns.z);
        vec4 y_ = floor(j - 7.0 * x_);
        vec4 x = x_ *ns.x + ns.yyyy;
        vec4 y = y_ *ns.x + ns.yyyy;
        vec4 h = 1.0 - abs(x) - abs(y);
        vec4 b0 = vec4(x.xy, y.xy);
        vec4 b1 = vec4(x.zw, y.zw);
        vec4 s0 = floor(b0)*2.0 + 1.0;
        vec4 s1 = floor(b1)*2.0 + 1.0;
        vec4 sh = -step(h, vec4(0.0));
        vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
        vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
        vec3 p0 = vec3(a0.xy, h.x);
        vec3 p1 = vec3(a0.zw, h.y);
        vec3 p2 = vec3(a1.xy, h.z);
        vec3 p3 = vec3(a1.zw, h.w);
        vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
        p0 *= norm.x;
        p1 *= norm.y;
        p2 *= norm.z;
        p3 *= norm.w;
        vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
        m = m * m;
        return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
    }
`

/* ═══════════════════════════════════════════════════════════
   Custom Post-Processing Shaders
   ═══════════════════════════════════════════════════════════ */

export const VignetteShader = {
    uniforms: {
        tDiffuse: { value: null },
        offset: { value: 1.0 },
        darkness: { value: 1.0 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float offset;
        uniform float darkness;
        varying vec2 vUv;
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            vec2 uv=(vUv-vec2(0.5))*vec2(offset);
            float vig=clamp(1.0-dot(uv,uv),0.0,1.0);
            texel.rgb*=mix(1.0,pow(vig,0.5),darkness);
            gl_FragColor=texel;
        }`,
}

export const ChromaticAberrationShader = {
    uniforms: {
        tDiffuse: { value: null },
        strength: { value: 0.005 },
        resolution: { value: new THREE.Vector2(1, 1) },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float strength;
        uniform vec2 resolution;
        varying vec2 vUv;
        void main(){
            vec2 dir=vUv-vec2(0.5);
            float d=length(dir);
            float s=strength*d*d;
            vec2 offset=dir*s;
            float r=texture2D(tDiffuse,vUv+offset).r;
            float g=texture2D(tDiffuse,vUv).g;
            float b=texture2D(tDiffuse,vUv-offset).b;
            float a=texture2D(tDiffuse,vUv).a;
            gl_FragColor=vec4(r,g,b,a);
        }`,
}

export const FilmGrainShader = {
    uniforms: {
        tDiffuse: { value: null },
        time: { value: 0.0 },
        intensity: { value: 0.05 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float time;
        uniform float intensity;
        varying vec2 vUv;
        float rand(vec2 co){return fract(sin(dot(co,vec2(12.9898,78.233)))*43758.5453);}
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            float noise=rand(vUv+vec2(time*0.01,time*0.007))*2.0-1.0;
            texel.rgb+=noise*intensity;
            gl_FragColor=texel;
        }`,
}

/**
 * AlphaRestoreShader — restores original alpha from a saved render target.
 * UnrealBloomPass destroys alpha (writes 1.0 everywhere via AdditiveBlending).
 * This pass takes RGB from the post-processed chain but alpha from the pre-bloom render.
 */
export const AlphaRestoreShader = {
    uniforms: {
        tDiffuse: { value: null },
        tAlpha: { value: null },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform sampler2D tAlpha;
        varying vec2 vUv;
        void main(){
            vec4 color=texture2D(tDiffuse,vUv);
            float alpha=texture2D(tAlpha,vUv).a;
            gl_FragColor=vec4(color.rgb*alpha, alpha);
        }`,
}

/**
 * AlphaSavePass — copies current readBuffer to a side render target (alphaRT)
 * to preserve alpha before bloom destroys it. Passes through unchanged.
 */
export class AlphaSavePass {
    enabled: boolean = true
    needsSwap: boolean = false
    renderToScreen: boolean = false
    clear: boolean = false
    targetRT: THREE.WebGLRenderTarget
    private _copyMat: THREE.ShaderMaterial
    private _fsQuad: any
    private _scene: THREE.Scene
    private _cam: THREE.OrthographicCamera

    constructor(targetRT: THREE.WebGLRenderTarget) {
        this.targetRT = targetRT
        this._copyMat = new THREE.ShaderMaterial({
            uniforms: { tDiffuse: { value: null } },
            vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
            fragmentShader: `uniform sampler2D tDiffuse;varying vec2 vUv;void main(){gl_FragColor=texture2D(tDiffuse,vUv);}`,
            depthTest: false,
            depthWrite: false,
        })
        const geo = new THREE.PlaneGeometry(2, 2)
        this._fsQuad = new THREE.Mesh(geo, this._copyMat)
        this._fsQuad.frustumCulled = false
        this._scene = new THREE.Scene()
        this._scene.add(this._fsQuad)
        this._cam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)
    }

    setSize(w: number, h: number) {
        this.targetRT.setSize(w, h)
    }

    render(renderer: THREE.WebGLRenderer, writeBuffer: any, readBuffer: any) {
        if (!this.enabled) return
        this._copyMat.uniforms.tDiffuse.value = readBuffer.texture
        const oldRT = renderer.getRenderTarget()
        renderer.setRenderTarget(this.targetRT)
        renderer.clear()
        renderer.render(this._scene, this._cam)
        renderer.setRenderTarget(oldRT)
    }

    dispose() {
        this._copyMat.dispose()
        this._fsQuad.geometry.dispose()
        this.targetRT.dispose()
    }
}

export const ColorGradingShader = {
    uniforms: {
        tDiffuse: { value: null },
        brightness: { value: 0.0 },
        contrast: { value: 1.0 },
        saturation: { value: 1.0 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float brightness;
        uniform float contrast;
        uniform float saturation;
        varying vec2 vUv;
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            texel.rgb+=brightness;
            texel.rgb=((texel.rgb-0.5)*contrast)+0.5;
            float lum=dot(texel.rgb,vec3(0.2126,0.7152,0.0722));
            texel.rgb=mix(vec3(lum),texel.rgb,saturation);
            gl_FragColor=vec4(max(texel.rgb,0.0),texel.a);
        }`,
}

/**
 * Apply effects/post-processing changes.
 */
export function applyEffectsChanges(st, cfg) {
    const {
        _bloom: bloom,
        _ssao: ssao,
        _colorGrading: colorGrading,
        _vignette: vignette,
        _chromaticAberration: chromaticAberration,
        _filmGrain: filmGrain,
        _pixelated: pixelated,
        _fxaa: fxaa,
    } = st

    // Tone mapping
    st._renderer.toneMapping =
        TONE_MAPPINGS[cfg.toneMapping] || THREE.ACESFilmicToneMapping
    st._renderer.toneMappingExposure = cfg.exposure

    // Bloom
    if (bloom) bloom.enabled = cfg.bloomEnabled
    if (bloom && cfg.bloomEnabled) {
        bloom.strength = cfg.bloomStrength
        bloom.threshold = cfg.bloomThreshold
        bloom.radius = cfg.bloomRadius
    }

    // SSAO
    if (ssao) {
        ssao.enabled = cfg.enableSSAO
        if (cfg.enableSSAO) {
            ssao.kernelRadius = cfg.ssaoRadius
            ssao.minDistance = cfg.ssaoMinDistance
            ssao.maxDistance = cfg.ssaoMaxDistance
        }
    }

    // DOF (Depth of Field) — disabled for orthographic camera
    const dof = st._dof
    if (dof) {
        dof.enabled = cfg.enableDOF && cfg.cameraType !== "orthographic"
        if (cfg.enableDOF) {
            dof.uniforms["focus"].value = cfg.dofFocus
            dof.uniforms["aperture"].value = cfg.dofAperture
            dof.uniforms["maxblur"].value = cfg.dofMaxBlur
        }
    }

    // Alpha save/restore: needed when bloom + transparent background
    const needAlphaFix =
        (cfg.bloomEnabled || cfg.enableDOF) && cfg.transparentBackground
    if (st._alphaSave) st._alphaSave.enabled = needAlphaFix
    if (st._alphaRestore) st._alphaRestore.enabled = needAlphaFix

    // Color grading
    if (colorGrading) colorGrading.enabled = cfg.enableColorGrading
    if (colorGrading && cfg.enableColorGrading) {
        colorGrading.uniforms.brightness.value = cfg.brightness
        colorGrading.uniforms.contrast.value = cfg.contrast
        colorGrading.uniforms.saturation.value = cfg.saturation
    }

    // Vignette
    if (vignette) vignette.enabled = cfg.enableVignette
    if (vignette && cfg.enableVignette) {
        vignette.uniforms.offset.value = cfg.vignetteOffset
        vignette.uniforms.darkness.value = cfg.vignetteDarkness
    }

    // Chromatic aberration
    if (chromaticAberration)
        chromaticAberration.enabled = cfg.enableChromaticAberration
    if (chromaticAberration && cfg.enableChromaticAberration) {
        chromaticAberration.uniforms.strength.value =
            cfg.chromaticAberrationStrength
    }

    // Film grain
    if (filmGrain) filmGrain.enabled = cfg.enableFilmGrain
    if (filmGrain && cfg.enableFilmGrain) {
        filmGrain.uniforms.intensity.value = cfg.filmGrainIntensity
    }

    // Framer/Figma-style tile pixelation
    if (pixelated) pixelated.enabled = cfg.enablePixelate
    if (pixelated && cfg.enablePixelate) {
        pixelated.setTilePixelateConfig?.(cfg)
    }

    // FXAA
    if (fxaa) fxaa.enabled = cfg.enableFXAA
}
